{
  "name": "安捷伦 DSO7054 数字存储示波器",
  "name_en": "Agilent DSO7054 Digital Storage Oscilloscope",
  "manufacturer": "Agilent Technologies",
  "description": "一款台式数字存储示波器，用于观察、触发、采集和测量电压随时间变化的波形，常用于电子电路、射频系统和实验装置中的信号调试与时域分析。",
  "description_en": "A benchtop digital storage oscilloscope used to view, trigger on, acquire, and measure voltage waveforms over time. It is commonly used for signal debugging and time-domain analysis in electronics, RF systems, and laboratory experiments.",
  "tag_hints": [
    "digital storage oscilloscope",
    "waveform acquisition",
    "triggering",
    "time-domain measurement",
    "electronics debugging",
    "bench oscilloscope"
  ],
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "将示波器复位到默认状态",
      "description_en": "Reset the oscilloscope to its default state."
    },
    {
      "action_name": "auto-clear_buffers",
      "description": "清除设备缓冲区和状态",
      "description_en": "Clear the device buffers and status."
    },
    {
      "action_name": "auto-autoscale",
      "description": "自动调整量程和时基以显示输入信号",
      "description_en": "Automatically adjust scaling and timebase to display the input signal."
    },
    {
      "action_name": "auto-channel_info",
      "description": "获取通道信息",
      "description_en": "Get channel information."
    },
    {
      "action_name": "auto-channel_coupling",
      "description": "获取或设置通道输入耦合方式",
      "description_en": "Get or set the channel input coupling."
    },
    {
      "action_name": "auto-channel_scale",
      "description": "获取或设置通道垂直刻度",
      "description_en": "Get or set the channel vertical scale."
    },
    {
      "action_name": "auto-channel_probe",
      "description": "获取或设置通道探头衰减系数",
      "description_en": "Get or set the channel probe attenuation factor."
    },
    {
      "action_name": "auto-channel_toggle",
      "description": "获取或设置通道开关状态",
      "description_en": "Get or set whether the channel is enabled."
    },
    {
      "action_name": "auto-channel_invert",
      "description": "获取或设置通道反相状态",
      "description_en": "Get or set whether the channel is inverted."
    },
    {
      "action_name": "auto-channel_position",
      "description": "获取或设置通道垂直位置",
      "description_en": "Get or set the channel vertical position."
    },
    {
      "action_name": "auto-trigger_channel",
      "description": "获取或设置触发源通道",
      "description_en": "Get or set the trigger source channel."
    },
    {
      "action_name": "auto-trigger_slope",
      "description": "获取或设置触发斜率",
      "description_en": "Get or set the trigger slope."
    },
    {
      "action_name": "auto-trigger_level",
      "description": "获取或设置指定通道的触发电平",
      "description_en": "Get or set the trigger level for a specified channel."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取或设置触发模式",
      "description_en": "Get or set the trigger mode."
    },
    {
      "action_name": "auto-horizontal_offset",
      "description": "获取或设置水平时间偏移",
      "description_en": "Get or set the horizontal time offset."
    },
    {
      "action_name": "auto-horizontal_scale",
      "description": "获取或设置水平时间刻度",
      "description_en": "Get or set the horizontal time scale."
    },
    {
      "action_name": "auto-trace",
      "description": "采集指定通道的波形轨迹",
      "description_en": "Acquire a waveform trace from the specified channel."
    },
    {
      "action_name": "auto-measure_setup",
      "description": "定义测量槽位的源通道和测量参数",
      "description_en": "Define the source channel and measurement parameter for a measurement slot."
    },
    {
      "action_name": "auto-measure",
      "description": "读取已配置测量槽位的测量值",
      "description_en": "Read the value from a configured measurement slot."
    }
  ]
}

